import{e as t,ab as a,a1 as o,m as s,r as i,p as n}from"./chunks/framework.BGh0NSIy.js";const g=JSON.parse('{"title":"Monthly Updates [April]","description":"April 2025 updates","frontmatter":{"title":"Monthly Updates [April]","description":"April 2025 updates","date":"2025-04-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/april-2025.md","filePath":"posts/april-2025.md"}'),l={name:"posts/april-2025.md"};function d(p,e,h,f,m,c){const r=a("Post");return o(),s("div",null,[i(r,{authors:"nbats"}),e[0]||(e[0]=n('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h1 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h1><ul><li><p>Added a <strong><a href="https://fmhy.net/other/selfhosting" target="_blank" rel="noreferrer">Guide</a></strong> to set up and run your own instance of FMHY locally.</p></li><li><p>Added a <strong><a href="https://greasyfork.org/en/scripts/528660-fmhy-safelink-guard" target="_blank" rel="noreferrer">Userscript</a></strong> version of the FMHY Safeguard.</p></li><li><p>You can now choose <a href="https://i.imgur.com/kXNRPjM.mp4" target="_blank" rel="noreferrer">custom text colors</a> for the site using the icons in the sidebar + updated the feedback system to be more prominent.</p></li><li><p>Cleaned up Drama Streaming section, removed dead / bad sites, and starred a few that seemed to work the best, <a href="https://i.imgur.com/E3QTrUn.png" target="_blank" rel="noreferrer">before vs after</a>.</p></li><li><p>Cleaned up Japanese Learning section, note that no sites were removed, just moved, <a href="https://i.imgur.com/wPboWjk.png" target="_blank" rel="noreferrer">before vs after</a>.</p></li><li><p>Added usage limit tags to the <a href="https://fmhy.net/ai#video-generation" target="_blank" rel="noreferrer">AI Video Generators</a>.</p></li><li><p>Better organized font section + split into <a href="https://fmhy.net/text-tools#font-text-generators" target="_blank" rel="noreferrer">Generators</a> and <a href="https://fmhy.net/text-tools#font-customization" target="_blank" rel="noreferrer">Customization</a>.</p></li><li><p>Added a few <a href="https://i.imgur.com/s7UGdIz.png" target="_blank" rel="noreferrer">New Criteria</a> to our streaming site grading system.</p></li></ul><hr><h1 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h1><ul><li><p>Starred <a href="https://fmhy.net/audio#download-sites" target="_blank" rel="noreferrer">DAB Music Player</a> in Audio DDL. Single-click FLAC album downloads, has web app + desktop apps for Windows, Mac, and Linux, with Android support coming soon.</p></li><li><p>Starred <a href="https://fmhy.net/storage#privacy-based" target="_blank" rel="noreferrer">IronFox</a> in Android Privacy Browsers. Firefox-based browser with a focus on privacy / security. Feature-rich, recommended by the LibreWolf dev team, and our community seems to really like it.</p></li><li><p>Starred <a href="https://fmhy.net/social-media-tools#twitch-adblockers" target="_blank" rel="noreferrer">AdGuardExtra</a> in Twitch Adblockers. This seems to be the best way to block them now.</p></li><li><p>Starred <a href="https://fmhy.net/social-media-tools#youtube-downloaders" target="_blank" rel="noreferrer">AMP4</a> in YouTube Video Downloaders, ad-free, supports playlists and 3-hour long videos.</p></li><li><p>Starred <a href="https://fmhy.net/privacy#web-privacy" target="_blank" rel="noreferrer">JustDeleteMe</a> in Web Privacy. Directory of links to more easily delete your accounts from web services.</p></li><li><p>Starred <a href="https://fmhy.net/audio" target="_blank" rel="noreferrer">PocketCasts</a> in Podcast Streaming. Popular iOS podcast player that recently added both desktop + web apps.</p></li><li><p>Starred <a href="https://fmhy.net/misc#flights" target="_blank" rel="noreferrer">ADS-B Exchange</a> in Flights section, one of the only sites that doesn&#39;t lock features behind paywalls.</p></li><li><p>Replaced star for xManager with <a href="https://fmhy.net/mobile#android-audio" target="_blank" rel="noreferrer">ReVanced Manager</a> in Ad-Free Spotify as it has more features, fewer issues, and xManager itself recommends it.</p></li><li><p>Removed star for Bark as it&#39;s limited, and star for Tortoise TTS as it doesn&#39;t sound good, and instead starred <a href="https://fmhy.net/ai#text-to-speech" target="_blank" rel="noreferrer">TTS Online</a>, which sounds better and has a 10k daily character limit.</p></li></ul><hr><h1 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h1><ul><li><p>Removed TorrentGalaxy, doesn&#39;t look like it&#39;s coming back anytime soon sadly.</p></li><li><p>Removed The Last Disaster from Audio DDL as they&#39;ve shut down.</p></li><li><p>Removed TOTV from Live TV as every channel seems to be YouTube videos now.</p></li><li><p>Unstarred Plex as they&#39;ve made remote streaming <a href="https://www.plex.tv/blog/important-2025-plex-updates/" target="_blank" rel="noreferrer">paid only</a>, and increased their prices at the same time.</p></li><li><p>Unstarred PSArips as their download process is very annoying.</p></li><li><p>Unstarred Bookracy as it&#39;s been having issues for a while now.</p></li></ul>',9))])}const b=t(l,[["render",d]]);export{g as __pageData,b as default};
